"use client";

import { forwardRef, useCallback, useImperativeHandle } from "react";
import { motion, useAnimate } from "motion/react";

import type { AnimatedIconHandle, AnimatedIconProps } from "./types";

const BrandQwenIcon = forwardRef<AnimatedIconHandle, AnimatedIconProps>(
  ({ size = 24, color = "currentColor", className = "" }, ref) => {
    const [scope, animate] = useAnimate();

    const start = useCallback(async () => {
      // Reset quickly before replaying to keep hover feedback crisp.
      await animate(".qwen-spin", { rotate: 0 }, { duration: 0 });
      await animate(
        ".qwen-shape",
        {
          opacity: 0.18,
          pathLength: 0.15,
          scale: 0.985,
          filter: "blur(0.8px)",
        },
        { duration: 0 },
      );

      await animate(
        ".qwen-shape",
        {
          opacity: [0.18, 1],
          pathLength: [0.15, 1],
          scale: [0.985, 1.02, 1],
          filter: ["blur(0.8px)", "blur(0px)"],
        },
        {
          duration: 0.65,
          ease: [0.22, 1, 0.36, 1],
          times: [0, 0.55, 1],
        },
      );

      animate(
        ".qwen-spin",
        { rotate: 360 },
        { duration: 5.5, ease: "linear", repeat: Number.POSITIVE_INFINITY },
      );
    }, [animate]);

    const stop = useCallback(() => {
      animate(
        ".qwen-spin",
        { rotate: 0 },
        { duration: 0.25, ease: "easeOut" },
      );
      animate(
        ".qwen-shape",
        {
          opacity: 1,
          pathLength: 1,
          scale: 1,
          filter: "blur(0px)",
        },
        { duration: 0.22, ease: "easeOut" },
      );
    }, [animate]);

    useImperativeHandle(
      ref,
      () => ({
        startAnimation: start,
        stopAnimation: stop,
      }),
      [start, stop],
    );

    return (
      <motion.svg
        ref={scope}
        onHoverStart={start}
        onHoverEnd={stop}
        fill={color}
        fillRule="evenodd"
        viewBox="0 0 24 24"
        height={size}
        width={size}
        style={{ flex: "none", lineHeight: 1, overflow: "visible" }}
        xmlns="http://www.w3.org/2000/svg"
        className={`qwen-icon cursor-pointer select-none ${className}`}
      >
        <title>Qwen</title>
        <motion.g className="qwen-spin" style={{ transformOrigin: "50% 50%" }}>
          <motion.path
            className="qwen-shape"
            initial={{ opacity: 1, pathLength: 1, scale: 1 }}
            style={{ transformOrigin: "50% 50%" }}
            d="M12.604 1.34c.393.69.784 1.382 1.174 2.075a.18.18 0 00.157.091h5.552c.174 0 .322.11.446.327l1.454 2.57c.19.337.24.478.024.837-.26.43-.513.864-.76 1.3l-.367.658c-.106.196-.223.28-.04.512l2.652 4.637c.172.301.111.494-.043.77-.437.785-.882 1.564-1.335 2.34-.159.272-.352.375-.68.37-.777-.016-1.552-.01-2.327.016a.099.099 0 00-.081.05 575.097 575.097 0 01-2.705 4.74c-.169.293-.38.363-.725.364-.997.003-2.002.004-3.017.002a.537.537 0 01-.465-.271l-1.335-2.323a.09.09 0 00-.083-.049H4.982c-.285.03-.553-.001-.805-.092l-1.603-2.77a.543.543 0 01-.002-.54l1.207-2.12a.198.198 0 000-.197 550.951 550.951 0 01-1.875-3.272l-.79-1.395c-.16-.31-.173-.496.095-.965.465-.813.927-1.625 1.387-2.436.132-.234.304-.334.584-.335a338.3 338.3 0 012.589-.001.124.124 0 00.107-.063l2.806-4.895a.488.488 0 01.422-.246c.524-.001 1.053 0 1.583-.006L11.704 1c.341-.003.724.032.9.34zm-3.432.403a.06.06 0 00-.052.03L6.254 6.788a.157.157 0 01-.135.078H3.253c-.056 0-.07.025-.041.074l5.81 10.156c.025.042.013.062-.034.063l-2.795.015a.218.218 0 00-.2.116l-1.32 2.31c-.044.078-.021.118.068.118l5.716.008c.046 0 .08.02.104.061l1.403 2.454c.046.081.092.082.139 0l5.006-8.76.783-1.382a.055.055 0 01.096 0l1.424 2.53a.122.122 0 00.107.062l2.763-.02a.04.04 0 00.035-.02.041.041 0 000-.04l-2.9-5.086a.108.108 0 010-.113l.293-.507 1.12-1.977c.024-.041.012-.062-.035-.062H9.2c-.059 0-.073-.026-.043-.077l1.434-2.505a.107.107 0 000-.114L9.225 1.774a.06.06 0 00-.053-.031zm6.29 8.02c.046 0 .058.02.034.06l-.832 1.465-2.613 4.585a.056.056 0 01-.05.029.058.058 0 01-.05-.029L8.498 9.841c-.02-.034-.01-.052.028-.054l.216-.012 6.722-.012z"
          />
        </motion.g>
      </motion.svg>
    );
  },
);

BrandQwenIcon.displayName = "BrandQwenIcon";

export default BrandQwenIcon;

import type { SVGMotionProps } from "motion/react";
import type { ComponentType } from "react";

export type HoverlyIconCategory = "All" | "Social" | "UI" | "Arrows";

export interface AnimatedIconHandle {
  startAnimation: () => void | Promise<void>;
  stopAnimation: () => void | Promise<void>;
}

export interface AnimatedIconProps
  extends Omit<SVGMotionProps<SVGSVGElement>, "ref"> {
  size?: number;
  color?: string;
  strokeWidth?: number;
  className?: string;
}

export type HoverlyIconProps = AnimatedIconProps;

export interface IconCliCommand {
  label: string;
  command: string;
}

export interface HoverlyIconRecord {
  slug: string;
  name: string;
  category: Exclude<HoverlyIconCategory, "All">;
  description: string;
  tags: string[];
  componentName: string;
  importPath: string;
  sourceCode: string;
  registryUrl: string;
  cliCommands: IconCliCommand[];
}

export type HoverlyIconComponent = ComponentType<AnimatedIconProps>;
